SELECT 
FROM user_voice_link
WHERE user_id = #{userId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND voice_asset_id = #{voiceAssetId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
LIMIT 1

SELECT COUNT(*)
FROM user_voice_link
WHERE user_id = #{userId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND voice_asset_id = #{voiceAssetId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
  AND is_deleted = 0

mapper.update:
UPDATE user_voice_link
nickname = #{nickname}, is_default = #{isDefault}, update_time = NOW()
WHERE link_id = #{linkId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}

UPDATE user_voice_link
SET is_default = 1, update_time = NOW()
WHERE link_id = #{linkId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}

UPDATE user_voice_link
SET deleted_at = #{deletedAt}, is_deleted = 1
WHERE link_id = #{linkId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}

UPDATE user_voice_link
SET deleted_at = NOW(), is_deleted = 1
WHERE voice_asset_id = #{voiceAssetId, typeHandler=com.echoes.voice.domain.voice.repository.typehandler.UUIDTypeHandler}
